import{_ as e,o as n,c as o,a5 as c}from"./chunks/framework.BfQ7H7Qx.js";const u=JSON.parse('{"title":"Team Guide — Quy trình phát triển tính năng BrandHub","description":"","frontmatter":{},"headers":[],"relativePath":"guides/team-workflow-guide.md","filePath":"guides/team-workflow-guide.md"}'),a={name:"guides/team-workflow-guide.md"};function d(i,t,r,h,s,l){return n(),o("div",null,[...t[0]||(t[0]=[c('<h1 id="team-guide-—-quy-trinh-phat-trien-tinh-nang-brandhub" tabindex="-1">Team Guide — Quy trình phát triển tính năng BrandHub <a class="header-anchor" href="#team-guide-—-quy-trinh-phat-trien-tinh-nang-brandhub" aria-label="Permalink to &quot;Team Guide — Quy trình phát triển tính năng BrandHub&quot;">​</a></h1><p>&gt; Navigation: <a href="./../">← Knowledge Base Hub</a> · <a href="./README.html">← Guides Index</a> · <a href="./../rule/feature-workflow.html">Feature Workflow</a> · <a href="./../rule/git-commit-convention.html">Git Convention</a> &gt; &gt; Hướng dẫn chuẩn cho toàn bộ 5 thành viên khi nhận và hoàn thành một task Jira (<code>DA-xxx</code>). &gt; Đọc kỹ trước khi bắt đầu. Mọi bước có tài liệu gốc tham chiếu đều ghi rõ đường dẫn.</p><hr><h2 id="_1-boi-canh-nguyen-tac-chung" tabindex="-1">1. Bối cảnh &amp; Nguyên tắc chung <a class="header-anchor" href="#_1-boi-canh-nguyen-tac-chung" aria-label="Permalink to &quot;1. Bối cảnh &amp; Nguyên tắc chung&quot;">​</a></h2><ul><li>Hệ thống chuẩn hóa <strong>141 Functional Requirements (<code>3.2.1</code>–<code>3.10.14</code>)</strong> tương ứng <strong>141 Use Cases (<code>UC-001</code>–<code>UC-141</code>)</strong> trên <strong>9 functional domains</strong> và <strong>6 Canonical System Roles</strong> (<code>Guest</code>, <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>, <code>Admin</code>).</li><li>Công việc giữa các service phụ thuộc lẫn nhau chặt chẽ, nên ai hoàn thành sớm hoặc thấy task có thể mở khóa cho đồng đội thì chủ động nhận trên Jira để đẩy nhanh tiến độ.</li><li><strong>Trước khi bắt đầu:</strong> pull code mới nhất của nhánh <code>develop</code> trên các repo liên quan (<code>brandhub-infrastructure</code>, <code>brandhub-business-service</code>, <code>brandhub-ai-service</code>, <code>brandhub-publisher-service</code>, <code>brandhub-web</code>, <code>brandhub-mobile-app</code>).</li></ul><hr><h2 id="_2-quy-trinh-8-buoc-thuc-thi" tabindex="-1">2. Quy trình 8 bước thực thi <a class="header-anchor" href="#_2-quy-trinh-8-buoc-thuc-thi" aria-label="Permalink to &quot;2. Quy trình 8 bước thực thi&quot;">​</a></h2><h3 id="buoc-1-—-nhan-task-tren-jira" tabindex="-1">Bước 1 — Nhận task trên Jira <a class="header-anchor" href="#buoc-1-—-nhan-task-tren-jira" aria-label="Permalink to &quot;Bước 1 — Nhận task trên Jira&quot;">​</a></h3><p>Mở Jira, xem task được giao, ghi nhớ mã task (ví dụ <code>DA-47</code>), kéo task sang <strong>In Progress</strong>.</p><p><strong>Nếu công việc phát sinh chưa có task trên Jira</strong> (ví dụ phát hiện qua audit/review, hoặc bug ngoài scope task đang làm):</p><ol><li>Tạo task Jira mới (Task hoặc Bug tùy loại), đặt tên theo đúng pattern <code>[DA-Exx-yy] &lt;Mô tả&gt;</code> — số <code>yy</code> nối tiếp task cuối cùng của epic đó (không trùng số).</li><li><strong>Gán vào đúng Epic</strong> (field <code>parent</code>) và <strong>gán đúng Sprint hiện tại đang active</strong> (field Sprint) — không để task mồ côi không epic/không sprint.</li><li>Ghi rõ trong description: <code>Ghi chú: Không có trong plan gốc — phát sinh từ &lt;lý do&gt;. Docs: &lt;đường dẫn liên quan&gt;.</code></li><li>Bổ sung ngay task đó vào <a href="./../plan/brandhub-master-plan.html">brandhub-master-plan.md</a> — thêm dòng vào bảng Epic tương ứng + mục chi tiết theo mẫu các task phát sinh.</li></ol><h3 id="buoc-2-—-cap-nhat-tai-lieu-report-3-srs-va-report-4-sdd" tabindex="-1">Bước 2 — Cập nhật tài liệu Report 3 (SRS) và Report 4 (SDD) <a class="header-anchor" href="#buoc-2-—-cap-nhat-tai-lieu-report-3-srs-va-report-4-sdd" aria-label="Permalink to &quot;Bước 2 — Cập nhật tài liệu Report 3 (SRS) và Report 4 (SDD)&quot;">​</a></h3><p>Mỗi task/FR thuộc baseline 141 FR cần đồng bộ với kho báo cáo chính thức <code>brandhub-final_report</code>:</p><ul><li><strong>Report 3 — SRS</strong> (<code>brandhub-final_report/report3/report3_official.docx</code>): viết hoặc cập nhật <strong>spec cho FR</strong> theo chuẩn 141 FR (xem <a href="#3-mẫu-spec-fr-cho-report-3-srs">§3</a>). Tuân thủ nghiêm ngặt 6 Canonical Roles (<code>Guest</code>, <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>, <code>Admin</code>), đánh số lại <code>Normal Flow</code> từ <code>1.</code>, tham chiếu <code>MSG01</code>–<code>MSG60</code> và <code>BR-01</code>–<code>BR-65</code> không kèm mã HTTP thô. Screenshot FE chèn ở Bước 7 kèm chú thích <code>Figure X - &lt;Function Name&gt;</code>.</li><li><strong>Report 4 — SDD</strong> (<code>brandhub-final_report/report4/</code>): cập nhật <strong>Sequence Diagram / Class Design</strong> tương ứng cho FR.</li></ul><p>Report 1 (<code>brandhub-final_report/report1/</code>) và Report 2 (<code>brandhub-final_report/report2/</code>) đã được chốt baseline quản lý dự án; khi cần đối chiếu phạm vi hãy kiểm tra trước với nhóm trưởng.</p><h3 id="buoc-3-—-đoc-tai-lieu-nghiep-vu-spec-md-ba" tabindex="-1">Bước 3 — Đọc tài liệu nghiệp vụ (<code>spec.md</code> + BA) <a class="header-anchor" href="#buoc-3-—-đoc-tai-lieu-nghiep-vu-spec-md-ba" aria-label="Permalink to &quot;Bước 3 — Đọc tài liệu nghiệp vụ (`spec.md` + BA)&quot;">​</a></h3><ol><li>Mở thư mục feature tương ứng tại <a href="./../feature/README.html">docs/feature/README.md</a>: <ul><li>Nếu là 1 trong 141 FR chuẩn của SRS: vào <code>docs/feature/srs/&lt;01..09-domain&gt;/&lt;3-x-y-slug&gt;/</code>.</li><li>Nếu là module nền tảng / cross-cutting / mobile: vào <code>docs/feature/modules/&lt;kebab-case&gt;/</code>.</li></ul></li><li>Đọc file <code>spec.md</code> và đối chiếu trực tiếp với bộ tài liệu phân tích nghiệp vụ tại <a href="./../ba/README.html">docs/ba/README.md</a>.</li><li>Nếu phát hiện <code>spec.md</code> hoặc BA thiếu sót / lệch nghiệp vụ → báo lên kênh chung của nhóm để chốt lại trước khi sửa.</li></ol><h3 id="buoc-4-—-viet-đu-4-tai-lieu-theo-chuan-spec-→-plan-→-task-→-test" tabindex="-1">Bước 4 — Viết đủ 4 tài liệu theo chuẩn <code>spec → plan → task → test</code> <a class="header-anchor" href="#buoc-4-—-viet-đu-4-tai-lieu-theo-chuan-spec-→-plan-→-task-→-test" aria-label="Permalink to &quot;Bước 4 — Viết đủ 4 tài liệu theo chuẩn `spec → plan → task → test`&quot;">​</a></h3><p>Mỗi thư mục feature bắt buộc có đủ 4 file theo quy định tại <a href="./../rule/feature-workflow.html">docs/rule/feature-workflow.md</a>:</p><table tabindex="0"><thead><tr><th>File</th><th>Vai trò</th><th>Trả lời câu hỏi</th></tr></thead><tbody><tr><td><code>spec.md</code></td><td>Đặc tả nghiệp vụ (đã rà soát ở Bước 3)</td><td><strong>Làm gì, cho ai, đúng ra sao</strong></td></tr><tr><td><code>plan.md</code></td><td>Kế hoạch triển khai kỹ thuật</td><td><strong>Làm thế nào</strong></td></tr><tr><td><code>task.md</code></td><td>Checklist phân rã công việc</td><td><strong>Làm từng bước gì, xong chưa</strong></td></tr><tr><td><code>test.md</code></td><td>Kịch bản test case</td><td><strong>Kiểm tra gì để biết đúng</strong></td></tr></tbody></table><p><strong>Quy định bắt buộc — áp dụng cho cả 141 FR chuẩn lẫn mọi thay đổi lên code đang chạy:</strong></p><ol><li><strong><code>spec.md</code></strong> — đối chiếu với <a href="./../ba/README.html">docs/ba/README.md</a> và file baseline <code>Các FR của hệ thống - Feature_Function Requirement.csv</code>. Không tự ý sửa lệch nghiệp vụ một mình khi chưa thống nhất với nhóm. Với mọi màn hình UI (<code>brandhub-web</code>, <code>brandhub-mobile-app</code>), bắt buộc khai báo key đa ngôn ngữ (<code>vi.json</code> + <code>en.json</code>) và hỗ trợ Light/Dark theme.</li><li><strong><code>plan.md</code></strong> — chỉ viết sau khi <code>spec.md</code> đã chốt.</li><li><strong><code>task.md</code></strong> — phân rã từng bước nhỏ từ <code>plan.md</code>.</li><li><strong><code>test.md</code></strong> — viết kịch bản kiểm thử phủ đủ happy case và unhappy/edge case trước hoặc song song với lúc code.</li><li><strong>Code</strong> — triển khai đúng theo 4 file. Nếu phát hiện vướng mắc nghiệp vụ lúc code, quay lại cập nhật từ <code>spec.md</code>.</li></ol><h3 id="buoc-5-—-viet-code-theo-đung-tai-lieu-tach-be-fe" tabindex="-1">Bước 5 — Viết code theo đúng tài liệu (tách BE / FE) <a class="header-anchor" href="#buoc-5-—-viet-code-theo-đung-tai-lieu-tach-be-fe" aria-label="Permalink to &quot;Bước 5 — Viết code theo đúng tài liệu (tách BE / FE)&quot;">​</a></h3><ul><li><strong>Backend (<code>brandhub-business-service</code> / <code>brandhub-ai-service</code> / <code>brandhub-publisher-service</code>)</strong>: <ul><li>Tuân thủ chuẩn kiến trúc dịch vụ tại <a href="./../architecture/README.html">docs/architecture/README.md</a> và chuẩn API response <code>ApiResponse&lt;T&gt;</code> tại <a href="./../api/api-response-format.html">docs/api/api-response-format.md</a>.</li><li>Tuân thủ <code>brandhub-business-service/rule.md</code> (package structure, ErrorCode enum, JPA/transaction convention, RS256 JWT/BCrypt security, clean code, unit/integration test coverage).</li></ul></li><li><strong>Frontend (<code>brandhub-web</code> / <code>brandhub-mobile-app</code>)</strong>: <ul><li>Đảm bảo responsive, semantic theme tokens (Light/Dark mode, không hardcode mã màu hex), đa ngôn ngữ song song (<code>vi.json</code> / <code>en.json</code>), TypeScript strict (không dùng <code>any</code>), kiến trúc component sạch theo <code>brandhub-web/rule.md</code>.</li></ul></li></ul><h3 id="buoc-6-—-tao-nhanh-commit-mo-pr-theo-chuan" tabindex="-1">Bước 6 — Tạo nhánh, Commit &amp; Mở PR theo chuẩn <a class="header-anchor" href="#buoc-6-—-tao-nhanh-commit-mo-pr-theo-chuan" aria-label="Permalink to &quot;Bước 6 — Tạo nhánh, Commit &amp; Mở PR theo chuẩn&quot;">​</a></h3><p>Tuân thủ nghiêm ngặt <a href="./../rule/git-commit-convention.html">docs/rule/git-commit-convention.md</a>:</p><ul><li><strong>Tên nhánh (bắt buộc):</strong> <code>&lt;type&gt;/DA-&lt;id&gt;-&lt;kebab-case&gt;</code> (ví dụ <code>feat/DA-47-user-schema</code>, <code>fix/DA-58-mobile-responsive</code>, <code>docs/DA-2-readme-setup</code>). Chỉ dùng chữ thường và dấu gạch ngang <code>-</code>.</li><li><strong>Commit message (bắt buộc bằng tiếng Anh):</strong> <code>&lt;type&gt;(DA-&lt;id&gt;): &lt;short description&gt;</code> (ví dụ <code>feat(DA-47): implement workspace member role validation</code>).</li><li><strong>Pull Request:</strong> mở PR về nhánh <code>develop</code>, tiêu đề chứa mã <code>DA-&lt;id&gt;</code>, kiểm tra hết conflict và dùng <strong>Squash and merge</strong>.</li></ul><h3 id="buoc-7-—-đong-task-tren-jira-chup-man-hinh" tabindex="-1">Bước 7 — Đóng task trên Jira &amp; Chụp màn hình <a class="header-anchor" href="#buoc-7-—-đong-task-tren-jira-chup-man-hinh" aria-label="Permalink to &quot;Bước 7 — Đóng task trên Jira &amp; Chụp màn hình&quot;">​</a></h3><ol><li>Kéo task <strong>In Progress → In Review</strong>, chờ review kết quả.</li><li>Sau khi được duyệt → kéo sang <strong>Done</strong>.</li><li>Chụp màn hình UI thực tế lưu vào kho minh chứng (<a href="./../screenshots/README.html">docs/screenshots/README.md</a>) và chèn vào <code>brandhub-final_report/report3/report3_official.docx</code>.</li></ol><h3 id="buoc-8-—-cap-nhat-trang-thai-tren-bang-theo-doi-141-fr" tabindex="-1">Bước 8 — Cập nhật trạng thái trên bảng theo dõi 141 FR <a class="header-anchor" href="#buoc-8-—-cap-nhat-trang-thai-tren-bang-theo-doi-141-fr" aria-label="Permalink to &quot;Bước 8 — Cập nhật trạng thái trên bảng theo dõi 141 FR&quot;">​</a></h3><p>Cập nhật các cột tiến độ (<code>Chạy được</code>, <code>Đầy đủ UI + Xong case</code>, <code>Tài liệu</code>) trong file chuẩn ở thư mục gốc workspace: <code>Các FR của hệ thống - Feature_Function Requirement.csv</code> (141 FR từ <code>3.2.1</code> đến <code>3.10.14</code>).</p><hr><h2 id="_3-mau-spec-fr-cho-report-3-srs" tabindex="-1">3. Mẫu spec FR cho Report 3 (SRS) <a class="header-anchor" href="#_3-mau-spec-fr-cho-report-3-srs" aria-label="Permalink to &quot;3. Mẫu spec FR cho Report 3 (SRS)&quot;">​</a></h2><p>&gt; Đồng bộ với cấu trúc chuẩn trong <code>brandhub-final_report/report3/report3_official.docx</code>.</p><h3 id="cac-muc-bat-buoc-cua-moi-fr-3-2-1–3-10-14" tabindex="-1">Các mục bắt buộc của mỗi FR (<code>3.2.1</code>–<code>3.10.14</code>) <a class="header-anchor" href="#cac-muc-bat-buoc-cua-moi-fr-3-2-1–3-10-14" aria-label="Permalink to &quot;Các mục bắt buộc của mỗi FR (`3.2.1`–`3.10.14`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Mục</th><th>Nội dung chuẩn</th></tr></thead><tbody><tr><td><strong>Function Trigger</strong></td><td>Sự kiện kích hoạt chức năng (Actor nào + thao tác trên màn hình/route nào).</td></tr><tr><td><strong>Function Description</strong></td><td><code>Actors / Roles:</code> (chỉ dùng tổ hợp 6 tên chuẩn: <code>Guest</code>, <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>, <code>Admin</code>), <code>Purpose</code>, <code>Interface</code>, <code>Data Processing</code>. Không chèn dòng <code>Related Use Case &amp; Artefacts</code>.</td></tr><tr><td><strong>Screen Layout</strong></td><td>Ảnh chụp màn hình thực tế kèm dòng chú thích in nghiêng căn giữa <code>Figure X - &lt;Function Name&gt;</code>.</td></tr><tr><td><strong>Data Specifications</strong></td><td>Input fields, System-generated data, Output, và Message codes (<code>MSG01</code>–<code>MSG60</code>, không ghi mã HTTP thô).</td></tr><tr><td><strong>Business Rules</strong></td><td>Liên kết các quy tắc nghiệp vụ áp dụng (<code>BR-01</code>–<code>BR-65</code>).</td></tr><tr><td><strong>Normal Flow</strong></td><td>Danh sách bước xử lý chính, luôn bắt đầu đánh số lại từ <code>1.</code>.</td></tr><tr><td><strong>Abnormal Cases</strong></td><td>Các luồng ngoại lệ và mã thông báo <code>MSGxx</code> tương ứng.</td></tr><tr><td><strong>Post-Conditions</strong></td><td>Trạng thái hệ thống và dữ liệu sau khi hoàn tất.</td></tr></tbody></table><hr><h2 id="_4-tai-lieu-tham-chieu-nhanh" tabindex="-1">4. Tài liệu tham chiếu nhanh <a class="header-anchor" href="#_4-tai-lieu-tham-chieu-nhanh" aria-label="Permalink to &quot;4. Tài liệu tham chiếu nhanh&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nội dung</th><th>Đường dẫn</th></tr></thead><tbody><tr><td>Quy trình 4 file feature (<code>spec → plan → task → test</code>)</td><td><a href="./../rule/feature-workflow.html">docs/rule/feature-workflow.md</a></td></tr><tr><td>Quy chuẩn Git Branch, Commit &amp; PR</td><td><a href="./../rule/git-commit-convention.html">docs/rule/git-commit-convention.md</a></td></tr><tr><td>Quy định làm việc nhóm</td><td><a href="/brandhub-infrastructure/view.html?file=rule/team-rules.html">docs/rule/team-rules.html</a></td></tr><tr><td>Chuẩn code Backend</td><td><code>brandhub-business-service/rule.md</code></td></tr><tr><td>Chuẩn code Frontend Web</td><td><code>brandhub-web/rule.md</code></td></tr><tr><td>Kho đặc tả Feature (<code>srs/</code> &amp; <code>modules/</code>)</td><td><a href="./../feature/README.html">docs/feature/README.md</a></td></tr><tr><td>Phân tích nghiệp vụ BA &amp; 141 Use Cases</td><td><a href="./../ba/README.html">docs/ba/README.md</a></td></tr><tr><td>Danh sách 141 FR gốc của hệ thống (CSV)</td><td><code>Các FR của hệ thống - Feature_Function Requirement.csv</code> (workspace root)</td></tr><tr><td>Báo cáo chính thức Report 1–7</td><td><code>brandhub-final_report/</code> (<code>report3/report3_official.docx</code>, <code>report4/</code>, ...)</td></tr><tr><td>Tài liệu thiết kế Database</td><td><a href="./../database/README.html">docs/database/README.md</a></td></tr><tr><td>Script khởi tạo DB (tạo mới từ đầu)</td><td><code>database/init/init-postgres-v2.sql</code>, <code>database/init/init-mongo.js</code></td></tr><tr><td>Script Migration DB (cập nhật DB đang chạy)</td><td><code>database/migrations/postgres/</code>, <code>database/migrations/mongodb/</code>, <code>database/migrations/neo4j/</code></td></tr></tbody></table><hr><h2 id="_5-tom-tat-luong-thuc-thi" tabindex="-1">5. Tóm tắt luồng thực thi <a class="header-anchor" href="#_5-tom-tat-luong-thuc-thi" aria-label="Permalink to &quot;5. Tóm tắt luồng thực thi&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Pull develop (infra + service repos)</span></span>\n<span class="line"><span>  → B1: Nhận task Jira (DA-xxx), kéo sang In Progress</span></span>\n<span class="line"><span>  → B2: Đồng bộ đặc tả vào brandhub-final_report (Report 3 SRS + Report 4 SDD)</span></span>\n<span class="line"><span>  → B3: Đọc spec.md (trong docs/feature/srs/ hoặc modules/) + docs/ba/</span></span>\n<span class="line"><span>  → B4: Hoàn thiện đủ 4 file spec.md → plan.md → task.md → test.md</span></span>\n<span class="line"><span>  → B5: Triển khai code BE / FE + viết test happy/unhappy cases</span></span>\n<span class="line"><span>  → B6: Tạo nhánh &lt;type&gt;/DA-&lt;id&gt;-&lt;kebab-case&gt;, commit tiếng Anh, mở PR về develop</span></span>\n<span class="line"><span>  → B7: Kéo Jira sang In Review → Done + bổ sung screenshot vào Report 3</span></span>\n<span class="line"><span>  → B8: Cập nhật trạng thái trên file CSV 141 FR ở gốc workspace</span></span></code></pre></div><hr><h2 id="_6-quy-đinh-cap-nhat-migrate-database" tabindex="-1">6. Quy định cập nhật &amp; migrate Database <a class="header-anchor" href="#_6-quy-đinh-cap-nhat-migrate-database" aria-label="Permalink to &quot;6. Quy định cập nhật &amp; migrate Database&quot;">​</a></h2><p>Toàn bộ script vận hành cơ sở dữ liệu đặt tại thư mục cấp cao nhất <code>database/</code> của <code>brandhub-infrastructure</code> (tách biệt với tài liệu thiết kế trong <a href="./../database/README.html">docs/database/README.md</a>). Hệ thống duy trì <strong>2 điểm vào song song</strong> và bắt buộc cập nhật <strong>cả hai</strong> mỗi khi thay đổi schema:</p><table tabindex="0"><thead><tr><th>Điểm vào</th><th>Đối tượng sử dụng</th><th>Vị trí trong <code>brandhub-infrastructure</code></th></tr></thead><tbody><tr><td><strong>File Migration riêng</strong></td><td>Thành viên / môi trường <strong>đã có DB đang chạy</strong> — chỉ chạy phần thay đổi tăng thêm mà không mất dữ liệu hiện có.</td><td><code>database/migrations/postgres/&lt;YYYY-MM-DD&gt;-&lt;slug&gt;.sql</code>&lt;br&gt;<code>database/migrations/mongodb/&lt;YYYY-MM-DD&gt;-&lt;slug&gt;.js</code>&lt;br&gt;<code>database/migrations/neo4j/&lt;YYYY-MM-DD&gt;-&lt;slug&gt;.cypher</code></td></tr><tr><td><strong>File Init gốc</strong></td><td>Máy mới, Docker local mới hoặc môi trường CI/test <strong>khởi tạo DB từ đầu</strong> — chạy 1 lần tạo ra đầy đủ schema mới nhất (97 bảng PG / 52 collection Mongo).</td><td><code>database/init/init-postgres-v2.sql</code>&lt;br&gt;<code>database/init/init-mongo.js</code></td></tr></tbody></table><p><strong>Quy trình bắt buộc khi thay đổi schema (thêm/sửa/xóa cột, bảng, collection, index, constraint):</strong></p><ol><li>Tạo file migration mới trong <code>database/migrations/{postgres,mongodb,neo4j}/</code> theo định dạng ngày <code>YYYY-MM-DD-&lt;kebab-case&gt;</code> và viết câu lệnh idempotent (<code>IF NOT EXISTS</code> / <code>IF EXISTS</code>) để chạy lại không gây lỗi.</li><li>Cập nhật <strong>đúng thay đổi tương ứng</strong> vào <code>database/init/init-postgres-v2.sql</code> (hoặc <code>database/init/init-mongo.js</code>) để schema khởi tạo mới khớp 100% với schema sau khi chạy toàn bộ lịch sử migration.</li><li>Nếu thay đổi liên quan đến cấu trúc thực thể cốt lõi, cập nhật tài liệu thiết kế tại <a href="./../database/README.html">docs/database/README.md</a>.</li><li>Ghi rõ tên file migration trong mô tả PR và thông báo trên kênh Slack để các thành viên khác pull về chạy cập nhật. Không sửa hoặc xóa các file migration cũ đã được merge vào <code>develop</code>.</li></ol>',48)])])}const p=e(a,[["render",d]]);export{u as __pageData,p as default};
